import * as T from './vendor/three.module.js';
const random=n=>{let v=Math.sin(n*91.17+78.2)*43917.6;return v-Math.floor(v);};
const geo=new T.BoxGeometry(1,1,1);
// Curved individual leaves, instanced in clusters rather than solid foliage blobs.
const leafGeo=new T.BufferGeometry();leafGeo.setAttribute('position',new T.Float32BufferAttribute([0,0,-.5,-.38,.03,-.12,-.4,.09,.2,0,.13,.55,.4,.09,.2,.38,.03,-.12,0,.08,.02],3));leafGeo.setIndex([0,1,6,1,2,6,2,3,6,3,4,6,4,5,6,5,0,6]);leafGeo.computeVertexNormals();
const mats={concrete:new T.MeshStandardMaterial({color:0x68675b,roughness:1}),rust:new T.MeshStandardMaterial({color:0x744a32,roughness:.95,metalness:.25}),bark:new T.MeshStandardMaterial({color:0x4b4636,roughness:1}),leaves:new T.MeshStandardMaterial({color:0x91a45e,roughness:.93,side:T.DoubleSide}),dark:new T.MeshStandardMaterial({color:0x202825,roughness:.88}),skin:new T.MeshStandardMaterial({color:0x9c8a76,roughness:.9})};
function block(g,x,y,z,w,h,d,material=mats.concrete){const m=new T.Mesh(geo,material);m.position.set(x,y,z);m.scale.set(w,h,d);g.add(m);return m;}
function foliage(g,seed,count=30,spread=4,height=0){count*=12;const inst=new T.InstancedMesh(leafGeo,mats.leaves,count),o=new T.Object3D(),color=new T.Color();for(let i=0;i<count;i++){o.position.set((random(seed+i)-.5)*spread,height+random(seed+i+100)*spread*.55,(random(seed+i+200)-.5)*spread);o.scale.set(.22+random(i+seed)*.4,.45,.3+random(i+seed+12)*.5);o.rotation.set(random(i)*3,random(i+8)*6,random(i+11)*3);o.updateMatrix();inst.setMatrixAt(i,o.matrix);color.setHSL(.19+random(seed+i)*.1,.34,.28+random(i+seed)*.18);inst.setColorAt(i,color);}g.add(inst);return inst;}
function human(seed,officer=false){const g=new T.Group(),cloth=new T.MeshStandardMaterial({color:officer?0x263642:[0x716655,0x4d5d50,0x654f45,0x6d7370][seed%4],roughness:1});block(g,0,1.1,0,.38,.58,.23,cloth);const head=new T.Mesh(new T.SphereGeometry(.14,8,6),mats.skin);head.position.y=1.53;g.add(head);if(officer)block(g,0,1.65,0,.29,.09,.28,cloth);const limbs=[];for(let side of [-1,1]){const leg=block(g,side*.12,.4,0,.13,.7,.15,cloth);const arm=block(g,side*.28,1.08,0,.12,.55,.13,cloth);limbs.push(leg,arm);}g.userData={limbs,seed};return g;}
export class Aftermath{
 constructor(world){this.world=world;this.people=[];this.signals=[];this.wrecks=[];this.ribbons=[];this.time=0;this.build();}
 build(){const w=this.world,c=w.config,edge=c.halfWidth+1.6;
 // Foliage spills onto curbs and grows vertically up existing facades.
 for(let i=0;i<60;i++){const g=new T.Group(),side=i%2?1:-1,s=10+i*14;foliage(g,i*70,22,5,.1);if(i%3===0){const trunk=block(g,0,3,0,.35,6,.35,mats.bark);trunk.rotation.z=side*.15;for(let j=0;j<5;j++){const branch=block(g,Math.cos(j*2)*.6,3.3+j*.42,Math.sin(j*2)*.6,.12,2.3,.12,mats.bark);branch.rotation.z=Math.cos(j*2)*.8;branch.rotation.x=Math.sin(j*2)*.7;}const crown=foliage(g,i*15,28,6,5);crown.scale.y=1.3;}if(i%4===0){for(let j=0;j<9;j++){const vine=foliage(g,i*83+j,7,2,j*2);vine.position.x=side*2.4;}}w.add(g,s,side*(edge+random(i)*2));}
 // Cracked concrete, rubble and roadway vegetation. Center lane remains traversable.
 for(let i=0;i<38;i++){const g=new T.Group(),side=i%2?1:-1;for(let j=0;j<6;j++){const m=block(g,(random(i*5+j)-.5)*3,.15+random(j+i)*.25,(random(i+j*7)-.5)*5,.3+random(i+j)*1.1,.2+random(j+i)*.4,.3+random(i*j+1),i%3?mats.concrete:mats.rust);m.rotation.set(random(i+j),random(i+j+8)*6,random(i*j)*.5);}foliage(g,i*29,9,3,0);w.add(g,40+i*22,side*(c.halfWidth-.8));}
 for(let i=0;i<14;i++){const g=new T.Group(),side=i%2?1:-1;const housing=block(g,0,4.5,0,.55,1.65,.45,mats.dark);block(g,0,2.1,0,.12,4.2,.12,mats.rust);const lights=[];for(let j=0;j<3;j++){const color=[0xb8412b,0xbaa444,0x498454][j],material=new T.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.1});const m=new T.Mesh(new T.SphereGeometry(.15,10,8),material);m.position.set(0,5.02-j*.49,.25);g.add(m);lights.push(material);}if(i%4===1)g.rotation.z=side*.2;this.signals.push({lights,index:i});w.add(g,55+i*62,side*edge);}
 for(let i=0;i<32;i++){const p=human(i,i%11===0),side=i%2?1:-1,s=22+i*25;w.add(p,s,side*(edge+.8+random(i)*2));this.people.push({g:p,s,side,seed:i});}
 // Burned cars: recognisable cabin silhouettes, missing glass and skewed wheels.
 for(let i=0;i<16;i++){const g=new T.Group(),side=i%2?1:-1;block(g,0,.62,0,1.8,.5,4.3,i%3?mats.rust:mats.dark);block(g,0,1.09,.1,1.5,.5,1.9,mats.dark);for(let x of [-.92,.92])for(let z of [-1.35,1.35]){const wheel=new T.Mesh(new T.CylinderGeometry(.35,.35,.22,10),mats.dark);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.35,z);g.add(wheel);}const hood=block(g,0,.95,-1.6,1.75,.08,1.15,mats.rust);hood.rotation.x=-.5;g.rotation.y=side*(.15+random(i)*.4);foliage(g,i*44,12,2,.4);const x=side*(c.halfWidth-1.3),s=115+i*51;w.add(g,s,x);this.wrecks.push({s,x,width:1.4});}
 // Crumbling masonry and boards are attached directly to building faces.
 for(let i=0;i<w.props.length;i++){const p=w.props[i];if(!p.g.children.some(o=>o.scale?.y>15))continue;const face=-Math.sign(p.x)*(p.g.children[0].scale.x/2+.08);for(let j=0;j<4;j++){let m=block(p.g,face,1.6+j*1.8,Math.sin(j+i)*4,.15,.14,3.2,mats.rust);m.rotation.x=(j%2?.2:-.22);}foliage(p.g,i*13,18,4,5).position.x=face;}
 // Windborne dust is instanced rather than hundreds of separate draw calls.
 this.dust=new T.InstancedMesh(new T.PlaneGeometry(.035,.07),new T.MeshBasicMaterial({color:0xc3c2a8,side:T.DoubleSide,transparent:true,opacity:.45,depthWrite:false}),250);w.group.add(this.dust);
 }
 update(position,time,lateral=0){this.time=time;for(const p of this.people){const step=Math.sin(time*3+p.seed);p.g.userData.limbs.forEach((l,i)=>l.rotation.x=step*(i%2?-.35:.35));p.g.position.z+=Math.sin(time*.18+p.seed)*7;p.g.rotation.y=p.side*Math.PI/2;const nearby=Math.abs(p.g.position.z)<12&&Math.abs(p.g.position.x-lateral)<5;if(nearby){p.g.position.x+=p.side*1.2;p.g.rotation.y=p.side*.5;}}
 for(const signal of this.signals){const phase=(time+signal.index*2)%40,active=phase<24?2:phase<26?1:0;signal.lights.forEach((m,i)=>m.emissiveIntensity=i===active?2.5:.03);}
 const o=new T.Object3D();for(let i=0;i<250;i++){o.position.set((random(i)-.5)*100+Math.sin(time*.15+i)*3,random(i+71)*25, -((random(i+93)*220+time*1.8)%220)+15);o.rotation.set(time*.6+i,time*.3+i,0);o.updateMatrix();this.dust.setMatrixAt(i,o.matrix);}this.dust.instanceMatrix.needsUpdate=true;}
 collision(position,lateral){for(const w of this.wrecks){const z=((w.s-position+70)%this.world.config.length+this.world.config.length)%this.world.config.length-70;if(Math.abs(z)<3&&Math.abs(lateral-w.x)<w.width+1)return w;}return null;}
}
